INSERT INTO `chapitres` (`id`, `cours_id`, `module_numero`, `titre`, `description`, `objectifs`, `ordre`, `quiz_id`, `date_creation`) VALUES
(1, 1, 1, 'Découverte du Web', 'Comprendre les fondamentaux du web : comment fonctionne Internet, le modèle client-serveur et l\'évolution vers HTML5.', 'Comprendre le modèle client-serveur, distinguer site web et application web, identifier les rôles de HTML/CSS/JS, connaître l\'histoire et les nouveautés de HTML5.', 1, NULL, '2026-05-24 19:18:45'),
(2, 1, 1, 'Installation de l\'environnement', 'Installer et configurer tous les outils nécessaires pour développer en HTML5 : éditeur de code, navigateur et outils de développement.', 'Installer VS Code et ses extensions utiles, configurer un navigateur pour les tests, maîtriser les outils de développement du navigateur.', 2, NULL, '2026-05-24 19:18:45'),
(3, 1, 1, 'Premier document HTML', 'Créer votre toute première page HTML5 valide et comprendre chaque ligne de la structure minimale.', 'Créer un fichier HTML, comprendre la structure minimale (DOCTYPE, html, head, body), afficher une page dans le navigateur.', 3, NULL, '2026-05-24 19:18:45'),
(4, 1, 2, 'Anatomie d\'une balise HTML', 'Comprendre en détail la structure d\'une balise HTML : éléments, balises ouvrantes/fermantes, éléments vides et bonnes pratiques.', 'Distinguer éléments et balises, comprendre l\'imbrication, identifier les éléments vides, appliquer les bonnes pratiques d\'écriture.', 4, NULL, '2026-05-24 19:18:45'),
(5, 1, 2, 'Les attributs HTML', 'Maîtriser les attributs HTML essentiels : id, class, title, lang, hidden, tabindex, draggable, contenteditable et spellcheck.', 'Utiliser les attributs globaux, comprendre id vs class, appliquer les attributs d\'accessibilité et d\'interaction.', 5, NULL, '2026-05-24 19:18:45'),
(6, 1, 3, 'Titres et paragraphes', 'Structurer le texte avec les titres hiérarchiques (h1 à h6), les paragraphes, les retours à la ligne et les séparateurs.', 'Utiliser correctement la hiérarchie des titres, créer des paragraphes, insérer des sauts de ligne et des lignes horizontales.', 6, NULL, '2026-05-24 19:18:45'),
(7, 1, 3, 'Mise en forme du texte', 'Appliquer les balises de mise en forme sémantique : strong, em, b, i, u, mark, small, del, ins, sub et sup.', 'Choisir la bonne balise selon le sens (importance vs style), utiliser mark pour surligner, créer des indices et exposants.', 7, NULL, '2026-05-24 19:18:45'),
(8, 1, 3, 'Citations et contenu sémantique', 'Utiliser les balises de citation (blockquote, q, cite), le code informatique (code, pre, samp, kbd, var) et les abréviations.', 'Citer correctement des sources, afficher du code informatique, structurer les adresses, utiliser abbr et time.', 8, NULL, '2026-05-24 19:18:45'),
(9, 1, 4, 'Hyperliens', 'Maîtriser la balise a sous toutes ses formes : liens absolus, relatifs, internes, ancres, téléchargement, email et téléphone.', 'Créer tous types de liens, comprendre chemins absolus vs relatifs, utiliser les ancres, créer des liens de téléchargement, email et téléphone.', 9, NULL, '2026-05-24 19:18:45'),
(10, 1, 4, 'Navigation Web', 'Concevoir des menus de navigation professionnels et une structure de navigation multi-pages cohérente.', 'Créer des menus de navigation accessibles, structurer la navigation entre les pages, appliquer les bonnes pratiques UX.', 10, NULL, '2026-05-24 19:18:45'),
(11, 1, 5, 'Images', 'Intégrer et optimiser des images en HTML5 : formats, attributs, responsive design et légendes.', 'Utiliser img avec src/alt/width/height, rendre les images responsives, utiliser picture et source, créer des figures avec légendes.', 11, NULL, '2026-05-24 19:18:45'),
(12, 1, 5, 'Audio', 'Intégrer des fichiers audio en HTML5 avec contrôles, lecture automatique et sources multiples.', 'Utiliser la balise audio, configurer controls/autoplay/loop/muted, fournir des sources multiples pour compatibilité.', 12, NULL, '2026-05-24 19:18:45'),
(13, 1, 5, 'Vidéo', 'Intégrer des vidéos en HTML5 avec contrôles, poster, preload et sous-titres.', 'Utiliser la balise video, configurer poster et preload, ajouter des sous-titres avec track, gérer la compatibilité navigateurs.', 13, NULL, '2026-05-24 19:18:45'),
(14, 1, 6, 'Listes ordonnées', 'Créer des listes numérotées avec ol et li, personnaliser le type de numérotation et le numéro de départ.', 'Utiliser ol avec type (1, A, a, I, i) et start, créer des listes ordonnées accessibles.', 14, NULL, '2026-05-24 19:18:46'),
(15, 1, 6, 'Listes non ordonnées', 'Créer des listes à puces avec ul et li pour les menus, les énumérations et les groupes d\'éléments.', 'Maîtriser ul pour les menus de navigation, les listes d\'éléments, combiner avec CSS pour le style.', 15, NULL, '2026-05-24 19:18:46'),
(16, 1, 6, 'Listes de définition', 'Utiliser les listes de définition (dl, dt, dd) pour les glossaires, les FAQs et les descriptions.', 'Créer des glossaires et FAQs avec dl/dt/dd, comprendre quand utiliser ce type de liste.', 16, NULL, '2026-05-24 19:18:46'),
(17, 1, 6, 'Listes imbriquées', 'Combiner différents types de listes pour créer des structures complexes et hiérarchiques.', 'Imbriquer correctement les listes, créer des menus déroulants en HTML pur, structurer des plans complexes.', 17, NULL, '2026-05-24 19:18:46'),
(18, 1, 7, 'Bases des tableaux', 'Créer des tableaux HTML simples avec table, tr, td et th pour présenter des données tabulaires.', 'Structurer un tableau de base, utiliser th pour les en-têtes, créer des lignes et cellules de données.', 18, NULL, '2026-05-24 19:18:46'),
(19, 1, 7, 'Structure avancée des tableaux', 'Organiser les tableaux complexes avec thead, tbody, tfoot et caption pour une meilleure sémantique.', 'Utiliser thead/tbody/tfoot, ajouter une légende avec caption, structurer pour l\'accessibilité.', 19, NULL, '2026-05-24 19:18:46'),
(20, 1, 7, 'Fusion de cellules', 'Fusionner des cellules horizontalement (colspan) et verticalement (rowspan) pour des mises en page complexes.', 'Utiliser rowspan et colspan, créer des tableaux avec cellules fusionnées, éviter les erreurs courantes.', 20, NULL, '2026-05-24 19:18:46'),
(21, 1, 8, 'Introduction au HTML sémantique', 'Comprendre l\'importance de la sémantique HTML pour le SEO, l\'accessibilité et la maintenabilité du code.', 'Distinguer balises sémantiques vs non sémantiques, comprendre l\'impact sur le SEO et l\'accessibilité.', 21, NULL, '2026-05-24 19:18:46'),
(22, 1, 8, 'Éléments de structure', 'Maîtriser les balises sémantiques HTML5 : header, nav, main, section, article, aside et footer.', 'Utiliser chaque balise dans son contexte approprié, structurer une page complète avec les éléments sémantiques.', 22, NULL, '2026-05-24 19:18:46'),
(23, 1, 8, 'Organisation complète d\'une page moderne', 'Mettre en pratique tous les éléments sémantiques pour créer une page web professionnelle complète.', 'Concevoir la structure complète d\'un site moderne, combiner tous les éléments sémantiques, valider la structure.', 23, NULL, '2026-05-24 19:18:46'),
(24, 1, 9, 'Introduction aux formulaires', 'Comprendre le fonctionnement des formulaires HTML : balise form, attributs action et method (GET vs POST).', 'Créer un formulaire fonctionnel, comprendre GET vs POST, configurer l\'action d\'envoi.', 24, NULL, '2026-05-24 19:18:46'),
(25, 1, 9, 'Champs de saisie', 'Maîtriser les types d\'input texte : text, password, email, tel, url et search avec leurs spécificités.', 'Utiliser chaque type d\'input selon le contexte, activer la validation native, optimiser pour mobile.', 25, NULL, '2026-05-24 19:18:46'),
(26, 1, 9, 'Champs numériques', 'Utiliser les inputs number et range pour la saisie de valeurs numériques avec min, max et step.', 'Créer des champs numériques avec contraintes, utiliser range pour des curseurs, valider les données numériques.', 26, NULL, '2026-05-24 19:18:46'),
(27, 1, 9, 'Date et heure', 'Exploiter les types d\'input pour les dates et heures : date, time, datetime-local, month et week.', 'Utiliser les sélecteurs de date natifs, configurer les formats, gérer la compatibilité navigateurs.', 27, NULL, '2026-05-24 19:18:46'),
(28, 1, 9, 'Choix utilisateur', 'Créer des boutons radio, cases à cocher et listes déroulantes (select, option, optgroup).', 'Utiliser radio pour choix unique, checkbox pour choix multiples, structurer des select avec optgroup.', 28, NULL, '2026-05-24 19:18:46'),
(29, 1, 9, 'Zones de texte', 'Utiliser textarea pour la saisie de textes longs avec redimensionnement et limites.', 'Configurer textarea avec rows/cols, limiter la saisie, activer le redimensionnement.', 29, NULL, '2026-05-24 19:18:46'),
(30, 1, 9, 'Boutons', 'Maîtriser les différents types de boutons : button, submit, reset et leurs comportements.', 'Créer des boutons de soumission, d\'annulation et d\'action, comprendre les différences de comportement.', 30, NULL, '2026-05-24 19:18:46'),
(31, 1, 9, 'Téléversement de fichiers', 'Permettre aux utilisateurs de téléverser des fichiers avec l\'input file et ses attributs.', 'Configurer l\'upload de fichiers, accepter des types spécifiques, gérer les fichiers multiples.', 31, NULL, '2026-05-24 19:18:46'),
(32, 1, 9, 'Validation HTML5', 'Exploiter la validation native HTML5 avec required, minlength, maxlength, pattern, min, max et step.', 'Valider les formulaires sans JavaScript, utiliser les attributs de validation, créer des patterns regex, afficher des messages d\'erreur personnalisés.', 32, NULL, '2026-05-24 19:18:46'),
(33, 1, 9, 'Éléments avancés des formulaires', 'Découvrir les éléments avancés : fieldset, legend, datalist, output, progress et meter.', 'Grouper des champs avec fieldset/legend, suggérer avec datalist, afficher des barres de progression.', 33, NULL, '2026-05-24 19:18:46'),
(34, 1, 10, 'iframe', 'Intégrer des pages externes dans votre site avec iframe et comprendre les enjeux de sécurité.', 'Utiliser iframe pour intégrer du contenu, configurer les attributs de sécurité (sandbox, allow), comprendre les risques XSS.', 34, NULL, '2026-05-24 19:18:46'),
(35, 1, 10, 'Contenu embarqué', 'Utiliser embed et object pour intégrer des contenus externes comme des PDF, des animations Flash ou des applications.', 'Intégrer des PDF et autres contenus avec embed/object, comprendre les alternatives modernes.', 35, NULL, '2026-05-24 19:18:46'),
(36, 1, 11, 'Métadonnées', 'Configurer les balises meta essentielles : charset, viewport, description, keywords et author pour le SEO.', 'Optimiser les métadonnées pour le référencement, configurer le viewport pour le responsive, déclarer l\'auteur.', 36, NULL, '2026-05-24 19:18:47'),
(37, 1, 11, 'Open Graph', 'Implémenter les balises Open Graph (og:title, og:description, og:image) pour un partage optimal sur les réseaux sociaux.', 'Créer des aperçus attrayants pour Facebook, Twitter et LinkedIn, tester avec les outils de validation.', 37, NULL, '2026-05-24 19:18:47'),
(38, 1, 11, 'Favicons', 'Ajouter des favicons et icônes pour tous les supports : navigateurs, iOS, Android et Windows.', 'Créer et intégrer des favicons multi-plateformes, utiliser link icon et les balises Apple/Android.', 38, NULL, '2026-05-24 19:18:47'),
(39, 1, 12, 'Introduction à l\'accessibilité', 'Comprendre les principes fondamentaux de l\'accessibilité web (WCAG) et son importance légale et éthique.', 'Connaître les normes WCAG 2.1, comprendre les 4 principes (perceptible, utilisable, compréhensible, robuste), identifier les publics concernés.', 39, NULL, '2026-05-24 19:18:47'),
(40, 1, 12, 'Accessibilité des images', 'Rendre les images accessibles avec des alternatives textuelles appropriées et des descriptions détaillées.', 'Rédiger des attributs alt pertinents, distinguer images décoratives vs informatives, utiliser longdesc et aria-describedby.', 40, NULL, '2026-05-24 19:18:47'),
(41, 1, 12, 'Accessibilité des formulaires', 'Créer des formulaires accessibles avec des labels explicites, des instructions claires et une navigation au clavier.', 'Associer labels et champs avec for/id, structurer avec fieldset/legend, gérer les erreurs de manière accessible.', 41, NULL, '2026-05-24 19:18:47'),
(42, 1, 12, 'Attributs ARIA', 'Utiliser les attributs ARIA (aria-label, aria-labelledby, aria-hidden, role) pour améliorer l\'accessibilité.', 'Appliquer aria-label pour nommer les éléments, utiliser role pour définir la fonction, masquer le contenu décoratif avec aria-hidden.', 42, NULL, '2026-05-24 19:18:47'),
(43, 1, 13, 'Canvas', 'Découvrir l\'élément Canvas pour dessiner des graphiques, des formes, du texte et manipuler des images en JavaScript.', 'Initialiser un canvas, dessiner des formes simples, écrire du texte, afficher et transformer des images.', 43, NULL, '2026-05-24 19:18:47'),
(44, 1, 13, 'SVG', 'Intégrer et créer des graphiques vectoriels SVG : rectangles, cercles, lignes, polygones et texte.', 'Créer des SVG de base, comprendre les coordonnées, utiliser les formes géométriques, styliser avec CSS.', 44, NULL, '2026-05-24 19:18:47'),
(45, 1, 13, 'Éléments interactifs', 'Utiliser les éléments interactifs HTML5 : details/summary pour du contenu pliable et dialog pour des boîtes de dialogue modales.', 'Créer du contenu expansible avec details/summary, implémenter des modales natives avec dialog, gérer l\'ouverture/fermeture.', 45, NULL, '2026-05-24 19:18:47'),
(46, 1, 14, 'Structure professionnelle d\'un projet HTML', 'Organiser un projet web professionnel : arborescence des dossiers, nommage des fichiers et conventions de code.', 'Créer une arborescence propre, nommer les fichiers correctement, adopter une convention de code cohérente.', 46, NULL, '2026-05-24 19:18:47'),
(47, 1, 14, 'Validation du code HTML', 'Valider votre code HTML avec le validateur W3C et corriger les erreurs pour un code propre et standard.', 'Utiliser le validateur W3C, comprendre les erreurs courantes, garantir un code conforme aux standards.', 47, NULL, '2026-05-24 19:18:47'),
(48, 1, 14, 'Performance', 'Optimiser les performances de vos pages HTML : minification, lazy loading, préchargement et cache.', 'Appliquer le lazy loading aux images/iframes, précharger les ressources critiques, optimiser le temps de chargement.', 48, NULL, '2026-05-24 19:18:47'),
(49, 1, 14, 'Référencement SEO avec HTML', 'Appliquer les techniques SEO on-page : structure des titres, balisage sémantique, données structurées et rich snippets.', 'Optimiser la hiérarchie des titres, utiliser le balisage sémantique pour le SEO, implémenter des données structurées Schema.org.', 49, NULL, '2026-05-24 19:18:47'),
(50, 1, 14, 'Compatibilité navigateurs', 'Assurer la compatibilité de votre code HTML avec tous les navigateurs modernes et gérer les spécificités.', 'Tester sur les navigateurs majeurs, utiliser Can I Use, gérer les préfixes et les polyfills, adopter l\'amélioration progressive.', 50, NULL, '2026-05-24 19:18:47'),
(51, 1, 14, 'Organisation d\'un site réel', 'Appliquer toutes les bonnes pratiques pour concevoir, structurer et livrer un site web professionnel complet.', 'Planifier l\'architecture d\'un site, créer une structure maintenable, documenter son code, préparer la mise en production.', 51, NULL, '2026-05-24 19:18:47'),
(52, 1, 15, 'Analyse du projet', 'Analyser le cahier des charges du projet final : objectifs, public cible, fonctionnalités attendues et contraintes techniques.', 'Lire et analyser un cahier des charges, identifier les besoins fonctionnels, planifier la structure HTML.', 52, NULL, '2026-05-24 19:18:47'),
(53, 1, 15, 'Création de la structure complète', 'Construire la structure HTML complète du projet en appliquant tous les éléments sémantiques appris.', 'Créer l\'arborescence des pages, structurer chaque page avec les balises sémantiques, organiser la navigation.', 53, NULL, '2026-05-24 19:18:47'),
(54, 1, 15, 'Mise en place des formulaires', 'Intégrer tous les formulaires du projet avec validation HTML5, accessibilité et expérience utilisateur optimale.', 'Créer des formulaires de contact, d\'inscription et de recherche avec validation complète et messages d\'erreur.', 54, NULL, '2026-05-24 19:18:47'),
(55, 1, 15, 'Intégration multimédia', 'Intégrer les images, vidéos et contenus externes dans le projet final de manière optimisée et accessible.', 'Optimiser et intégrer les médias, appliquer le lazy loading, assurer l\'accessibilité des contenus multimédias.', 55, NULL, '2026-05-24 19:18:47'),
(56, 1, 15, 'Accessibilité', 'Vérifier et améliorer l\'accessibilité du projet final selon les normes WCAG 2.1 niveau AA.', 'Auditer l\'accessibilité avec des outils automatisés, tester au clavier, vérifier les contrastes, corriger les problèmes.', 56, NULL, '2026-05-24 19:18:47'),
(57, 1, 15, 'Optimisation SEO', 'Appliquer les techniques SEO on-page au projet final : métadonnées, Open Graph, données structurées et performances.', 'Optimiser les balises title/meta, implémenter Open Graph et Twitter Cards, ajouter des données structurées JSON-LD.', 57, NULL, '2026-05-24 19:18:47'),
(58, 1, 15, 'Validation finale', 'Valider l\'ensemble du projet : code HTML, performance, accessibilité, SEO et compatibilité avant livraison.', 'Passer le validateur W3C, tester sur tous les navigateurs, mesurer les performances, livrer un projet professionnel.', 58, NULL, '2026-05-24 19:18:47');
